INSERT INTO corpus_ingest.cleanup_decisions(dataset,record_id,issue,disposition,reason,evidence,original_record,run_id)
SELECT r.dataset,r.id,'native_testing_court_in_public_registry','quarantine','Publisher court jurisdiction T is a testing court; the historical public projection mislabeled T as Territory. Preserve full original row in this reversible private archive and exclude it from the active court registry.',jsonb_build_object('provider','courtlistener','native_id',e.native_id,'source_schema','CourtListener September 2026 bulk court metadata','native_jurisdiction',e.data->>'jurisdiction','source_payload_sha256',e.payload_sha256,'original_dataset',(SELECT to_jsonb(d) FROM public.corpus_datasets d WHERE d.id=r.dataset)),to_jsonb(r),'494cfa52-74c5-42ac-a770-80e46b9a3035'::uuid
FROM public.corpus_records r JOIN corpus_ingest.entities e ON e.source_system='courtlistener' AND e.entity_type='courts' AND e.native_id=r.id AND e.data->>'jurisdiction'='T'
WHERE r.dataset='court_spine' AND r.id IN('psc','test') ON CONFLICT DO NOTHING;
DELETE FROM public.corpus_records r WHERE r.dataset='court_spine' AND r.id IN('psc','test') AND EXISTS(SELECT 1 FROM corpus_ingest.cleanup_decisions d WHERE d.dataset=r.dataset AND d.record_id=r.id AND d.issue='native_testing_court_in_public_registry' AND d.disposition='quarantine' AND d.original_record->>'id'=r.id);
UPDATE public.corpus_datasets d SET expected_records=c.n,imported_records=c.n,metadata=d.metadata||jsonb_build_object('testing_court_quarantine','2026-10-02','quarantined_records',2,'source_records_before_quarantine',5413),updated_at=now() FROM(SELECT count(*) n FROM public.corpus_records WHERE dataset='court_spine')c WHERE d.id='court_spine';
SELECT count(*) active_records FROM public.corpus_records WHERE dataset='court_spine';